import React, { useState } from "react";
import AdminProductDetails from "../AdminProductDetails/AdminProductDetails";
import ProductList from "../ProductList/AdminProductList";
import AdminOrderList from "../Orders/AdminOrderList";
import OrderDetails from "../Orders/OrderDetails";
import "./AdminContainer.scss";

const AdminContainer = (props) => {
  const [selectedProduct, setSelectedProduct] = useState(null); // Contient les détails du produit sélectionné
  const [selectedOrder, setSelectedOrder] = useState(null);
  const [showProductList, setShowProductList] = useState(true);

  const handleProductDetails = (product) => {
    console.log("Selected product:", product); // Vérification si stock est présent
    setSelectedProduct(product); // Inclut toutes les données du produit, y compris stock
  };

  const handleOrderDetails = (order) => {
    setSelectedOrder(order);
  };

  const onBackClickToProductList = () => {
    setSelectedProduct(null);
    setSelectedOrder(null);
    setShowProductList(true);
  };

  const onBackClickToOrderDetails = () => {
    setSelectedProduct(null);
    setSelectedOrder(null);
    setShowProductList(false);
  };

  return (
    <div className="admin-container">
      {selectedProduct ? (
        <div className="details-container">
          {/* Passer toutes les données du produit, y compris stock */}
          <AdminProductDetails
            product={selectedProduct} // Inclut stock
            onBackClick={onBackClickToProductList}
          />
        </div>
      ) : (
        <>
          <div>
            {showProductList ? (
              <div className="product-list-container">
                <button onClick={() => setShowProductList(false)}>
                  Get Order List
                </button>
                {/* Passer handleProductDetails pour sélectionner un produit */}
                <ProductList handleProductDetails={handleProductDetails} />
              </div>
            ) : (
              <div className="order-list-container">
                {selectedOrder ? (
                  <div className="details-container">
                    <OrderDetails
                      orderId={selectedOrder.orderId}
                      onBackClick={onBackClickToOrderDetails}
                    />
                  </div>
                ) : (
                  <div>
                    <button onClick={() => setShowProductList(true)}>
                      Get Product List
                    </button>
                    <AdminOrderList handleOrderDetails={handleOrderDetails} />
                  </div>
                )}
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
};

export default AdminContainer;
